randKey: string, // minLength: 1, maxLength: 200
}
>,
// 추가할 참석자. attendanceType(ID|EMAIL) + attendanceInfo 필수.
addAttendances?: Array<
{
attendanceInfo: string, // minLength: 1, maxLength: 200
attendanceName?: string, // minLength: 1, maxLength: 100
attendanceType: "ID" | "EMAIL",
}
>,
// 추가할 알림. notificationType 은 "ALARM" 고정, notificationTime 은 일정 전 분(minutes) 숫자 문자열.
addNotifications?: Array<
{
notificationTime: string, // pattern: /^[0-9]+$/
notificationType: "ALARM",
}
>,
allDayYn: "Y" | "N",
// 이동할 캘린더 ID(숫자 문자열). 캘린더 변경 시.
calendarSrno?: string, // pattern: /^\d+$/
// 제거할 첨부.
deleteAttachments?: Array<
