{
// flow_get_project(include:["columns"])의 columnId.
columnId: string, // pattern: /^\d+$/
// TEXT=문자열, NUMBER=숫자, CHECKBOX=boolean, DATE=날짜 문자열, OPTION/USER=ID 또는 ID 배열, 삭제=null.
