 | number
 | boolean
// minItems: 1, maxItems: 100
 | Array<
string // minLength: 1, maxLength: 100
>
)
 | null
,
}
>,
// YYYYMMDD
endDate?: string, // pattern: /^\d{8}$/
// 우선순위: low/normal/high/urgent, none=해제.
priority?: "low" | "normal" | "high" | "urgent" | "none",
// 업무가 속한 프로젝트 ID(colabo_srno).
projectId: string, // pattern: /^\d+$/
// YYYYMMDD
startDate?: string, // pattern: /^\d{8}$/
// 기본 업무 상태: request=요청, progress=진행, feedback=피드백, complete=완료, hold=보류.
status?: "request" | "progress" | "feedback" | "complete" | "hold",
// **커스텀 상태** 옵션 ID(option_srno). 프로젝트가 flow_set_statuses 로 자체 단계(기획/개발/QA…)를 쓰는 경우 base 5상태로는 옮길 수 없어 이 값을 쓴다. ID 는 flow_get_project(include:["statuses"]) 의 id. status 와 **동시에 지정할 수 없다**(계약이 XOR 강제).
statusOptionSrno?: string, // pattern: /^\d+$/
// 수정할 업무 ID(숫자 문자열) **한 건**. flow_query_tasks 결과의 taskId 나 flow_get_post 의 tasks[].taskId 로 확보 — 게시물 postId 와 다르다. taskIds 와 동시에 지정할 수 없다.
taskId?: string, // pattern: /^\d+$/
// **같은 변경을 여러 업무에 한 번에** 적용할 때의 업무 ID 목록(최대 50건). 상태 일괄 이동이 대표 용례다. 순차 적용하며 한 건이 실패해도 나머지는 계속하고, 응답의 results 에 업무별 결과가 담긴다. taskId 와 동시에 지정할 수 없다.
// minItems: 1, maxItems: 50
taskIds?: Array<
string // pattern: /^\d+$/
>,
// 담당자를 **이름으로** 지정. 서버가 같은 회사 안에서 정확히 같은 이름 한 명으로 풀고, 동명이인이면 후보를 알려 거절한다. flow_find_employees 의 userId 가 `<<email-N>>` 처럼 가려져 오면 그 값 대신 이걸 쓴다. workers 와 합쳐 전체 목록이 된다(교체).
// minItems: 1, maxItems: 50
workerNames?: Array<
{
// 동명이인일 때 부서 이름.
divisionName?: string, // minLength: 1, maxLength: 100
// 구성원 이름(근태 꼬리·호칭 없이).
name: string, // minLength: 1, maxLength: 50
}
>,
// 담당자 **전체 목록**(교체). 여기 없는 기존 담당자는 제거된다 — 추가하려면 기존 담당자를 모두 포함해 보낼 것. 현재 담당자는 flow_get_post 로 확인. workerId 는 flow_find_employees 또는 flow_get_project(include:["participants"]) 로 해소.
workers?: Array<
{
workerId: string, // minLength: 1, maxLength: 100, pattern: /^[a-zA-Z0-9\-_@\.]+$/
}
>,
}): Promise<{ failed?: { error: string, field: string }[], results?: { failed: { error: string, field: string }[], taskId: string, updated: string[] }[], summary?: { failed: number, ok: number, total: number }, updated?: string[] }>;
