// What kind of problem this was. usability: hard to understand or use correctly, such as a confusing name or unclear parameters. reliability: behaved inconsistently, failed unexpectedly, or returned unusable results. documentation: the tool or operation's own description, schema or guidance was missing, unclear or misleading (not about published documentation pages). efficiency: took more calls, steps or tokens than it should have. interoperability: did not compose well with other tools, operations or formats. could-not-accomplish: nothing available could do what was needed.
category: "usability" | "reliability" | "documentation" | "efficiency" | "interoperability" | "could-not-accomplish",
// One short sentence naming the problem, in your own words.
summary: string, // minLength: 1, maxLength: 256
// Name of the tool or entry point the problem was with, e.g. "invoke_operation". Omit when nothing available could do what you needed.
toolName?: string,
// The operation the tool was pointed at, when toolName is invoke_operation or describe_operation, e.g. "updateChangeRequestContent". Leave out for search: a search that found nothing has no operation to name.
target?: string,
// low for minor friction, high for a task you could not complete.
severity?: "low" | "medium" | "high",
// What happened, step by step: what you were trying, what you called in what order, what you expected, and what you got instead. Enough for someone to follow without guessing. Never include parameter values.
detail?: string,
// What you were trying to accomplish, without any PII.
goal?: string,
// How you worked around it, if you managed to.
workaround?: string,
// How many times you tried.
callCount?: integer, // minimum: 0, maximum: 9007199254740991
// How many of those worked.
successCount?: integer, // minimum: 0, maximum: 9007199254740991
// The correlationId you were given when the call failed. Copy it exactly; it is how the report is matched to the logs of that call.
correlationId?: string,
// The model you are running as, if you know it.
model?: string,
// True when the user explicitly asked you to report this.
onDemand?: boolean,
}): Promise<unknown>;
